 c={root,items,keptItems:kept,opacity:1,cleanupImageGeometry:{frame:f.frame},restoredPanelGeometry:geometry,restoredSourcePanels:restored,minimumFontSize:5,aidokuReadableMinimum:8.5,scrollX:0,scrollY:0,currentlyCommitting:false,performance:{now:()=>0},setKoreanFont:s=>c.font=parseFloat(s.split(' ')[1]),koreanTextWidth:w=>w.length*c.font*.55,document:{createRange:()=>({selectNodeContents(n){this.node=n;},getBoundingClientRect(){return this.node._ink();}})}};
